class Solution {
    public int largestInteger(int num){
        char[] digits=Integer.toString(num).toCharArray();
        List<Character> odd=new ArrayList<>(),even=new ArrayList<>();
        for(char digit:digits)(digit%2==0?even:odd).add(digit);
        odd.sort(Collections.reverseOrder());
        even.sort(Collections.reverseOrder());
        int o=0,e=0;
        for(int i=0;i<digits.length;i++)digits[i]=digits[i]%2==0?even.get(e++):odd.get(o++);
        return Integer.parseInt(new String(digits));
    }
}

code.kotlin:
class Solution {
    fun largestInteger(num:Int):Int{
        val digits=num.toString().toCharArray();
        val odd=digits.filter{
            (it-'0')%2==1
        }.sortedDescending();
        val even=digits.filter{
            (it-'0')%2==0
        }.sortedDescending();
        var o=0;
        var e=0;
        for(i in digits.indices)digits[i]=if((digits[i]-'0')%2==0)even[e++]else odd[o++];
        return String(digits).toInt()
    }
}

